int handle(struct pool *p, const struct request *r)
{
    if (r == NULL || r->len == 0)
        return -EINVAL;                 /* refuse before touching the pool */
    if (pool_full(p))
        return -EBUSY;                  /* fail fast, never queue */
    struct conn *c = pool_try_acquire(p);
    if (c == NULL)
        return -ENOMEM;
    int rc = conn_serve(c, r);
    pool_release(p, c);                 /* cleanup on every exit path */
    return rc;
}
